class Solution {
public:
    bool checkValidString(string s) {
        int cmin = 0, cmax = 0;
        for (char ch : s) {
            if (ch == '(') {
                cmin++;
                cmax++;
            } else if (ch == ')') {
                cmin--;
                cmax--;
            } else {
                cmin--;
                cmax++;
            }
            if (cmax < 0) return false;
            cmin = max(cmin, 0);
        }
        return cmin == 0;
    }
};

class Solution {
    public boolean checkValidString(String s) {
        int cmin = 0, cmax = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                cmin++;
                cmax++;
            } else if (ch == ')') {
                cmin--;
                cmax--;
            } else {
                cmin--;
                cmax++;
            }
            if (cmax < 0) return false;
            cmin = Math.max(cmin, 0);
        }
        return cmin == 0;
    }
}

var checkValidString = function(s) {
    let cmin = 0;
    let cmax = 0;
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (ch === '(') {
            cmin++;
            cmax++;
        } else if (ch === ')') {
            cmin--;
            cmax--;
        } else {
            cmin--;
            cmax++;
        }
        if (cmax < 0) return false;
        cmin = Math.max(cmin, 0);
    }
    return cmin === 0;
};
